2. Scripts de Automação dos Áudios


Script de Mixagem (scripts/mix-prayer.py)



Mixa o áudio de voz pura gerado pelo TTS com a trilha sonora de fundo:



"""Mix a voice-only prayer MP3 with the shared background music from the manifest.
Usage: python3 scripts/mix-prayer.py <voice.mp3> <out.mp3>"""
import json, subprocess, sys, urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
m = json.loads((ROOT / "src/lib/prayer-recordings.json").read_text())["music"]
music = Path("/tmp/prayer-music.mp3")
if not music.exists():
    url = json.loads((ROOT / m["asset"]).read_text())["url"]
    subprocess.run(["curl", "-sfo", str(music), f"http://localhost:8080{url}"], check=True)

voice, out = sys.argv[1], sys.argv[2]
dur = float(subprocess.check_output([
    "ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", voice
]))
total = m["intro"] + dur + m["outro"]
ms = int(m["intro"] * 1000)

filter_complex = (
    f"[1:a]atrim=0:{total},volume={m['volume']},afade=t=in:d=1.5,afade=t=out:st={total-3}:d=3[bg];"
    f"[0:a]adelay={ms}|{ms},apad[v];"
    f"[v][bg]amix=inputs=2:duration=shortest:normalize=0,atrim=0:{total}[o]"
)

subprocess.run([
    "ffmpeg", "-y", "-v", "error", "-i", voice, "-i", str(music),
    "-filter_complex", filter_complex,
    "-map", "[o]", "-ac", "1", "-b:a", "128k", out
], check=True)



Script de Renderização (scripts/render-prayer.py)



Lê o texto do manifesto e dispara a síntese na voz padrão V3:



"""Render one prayer with the versioned voice settings; never upload automatically."""
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
manifest = json.loads((ROOT / "src/lib/prayer-recordings.json").read_text())
key = sys.argv[1]
recording = next((r for r in manifest["recordings"] if r["key"] == key), None)
if recording is None:
    raise SystemExit(f"Unknown prayer: {key}")

folder = Path("/tmp/prayers-v3")
folder.mkdir(parents=True, exist_ok=True)
prompt = folder / f"{key}.txt"
prompt.write_text(recording["text"])
settings = manifest["synthesis"]

subprocess.run([
    "lovable", "audio", "generate", "--model", settings["model"],
    "--prompt-file", str(prompt), "--out", str(folder / f"{key}.mp3"),
    "--set", f"voice={settings['voice']}",
    "--set", f"speed={settings['speed']}",
    "--set", f"instructions={settings['instructions']}",
    "--set", "response_format=mp3",
], check=True)

# Aplica mixagem com fundo musical
subprocess.run([
    "python3", str(ROOT / "scripts/mix-prayer.py"),
    str(folder / f"{key}.mp3"),
    str(folder / f"{key}-musica.mp3")
], check=True)





3. Código do Mapeamento de Orações (src/lib/prayers.ts)



Carrega dinamicamente em tempo de build os ponteiros dos arquivos de áudio de cada mensagem (ou recorre à oração geral caso alguma mensagem não tenha áudio próprio):



import general from "@/assets/oracao-da-manha.mp3.asset.json";

type Pointer = { url: string };
const files = import.meta.glob<Pointer>("@/assets/oracoes/*.mp3.asset.json", { eager: true, import: "default" });

/** Message-specific prayer audio, keyed by message id. */
const byMessage: Record<string, string> = {};
for (const [path, p] of Object.entries(files)) {
  const id = path.split("/").pop()!.replace(".mp3.asset.json", "");
  byMessage[id] = p.url;
}

export type Prayer = { key: string; url: string; filename: string };

/** Returns the prayer recorded for this message, or the general morning prayer. */
export function prayerFor(messageId?: string): Prayer {
  const url = messageId ? byMessage[messageId] : undefined;
  if (messageId && url) return { key: messageId, url, filename: `oracao-${messageId}.mp3` };
  return { key: "geral", url: general.url, filename: "oracao-da-manha.mp3" };
}

export function hasOwnPrayer(messageId: string): boolean {
  return messageId in byMessage;
}





